{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "Local education agencies (LEAs) that install these cameras must enter into a memorandum of understanding with local law enforcement regarding enforcement and evidence review.",
      "rationale": "Conveys the camera-installing LEA's mandatory agreement with local law enforcement and both required subjects: evidence review and enforcement."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "Generally, only state-commissioned or POST-certified law enforcement officers, including school resource officers, are authorized to review camera evidence to determine if a violation occurred.",
      "rationale": "Conveys the default restriction, both qualifying officer categories, inclusion of school resource officers, and the purpose of determining violations."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "Additionally, an LEA may authorize school safety personnel to review this evidence.",
      "rationale": "Conveys the LEA's optional authorization of an additional review process. In context, this supplements the mandatory law-enforcement agreement rather than replacing it."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "This review process can happen concurrently with law enforcement review.",
      "rationale": "Expressly conveys concurrent review and, read with the mandatory agreement requirement, preserves law-enforcement participation when school personnel review evidence."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "For this purpose, school safety personnel include school resource officers, school safety officers, or other employees or contractors whose duties involve campus security or student safety.",
      "rationale": "Conveys all defined personnel categories and the qualifying safety or security duties; the surrounding LEA context supplies the employment or contracting relationship."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "The act would take effect immediately upon becoming law.",
      "rationale": "Accurately states the effective-date trigger."
    }
  ]
}
